Translate the following GNU C++0x code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <string>
#include <cstdlib>
#include <vector>
#include <cmath>
using namespace std;

typedef long long integer;
#define length(c) (int)(c).size()

long long compute_gcd(long long a, long long b) {
    while( b != 0 )
        a %= b, swap(a, b);
    return a;
}

int main() {
    long long a, b, limit; cin >> a >> b >> limit;
    long long best_num, best_den;
    double min_difference = 1e12;
    for(long long denom = 1; denom <= limit; denom++) {
        long long left = 0, right = 100000;
        long long numerator = 0;
        while( left <= right ) {
            long long mid = (left + right) >> 1;
            if( mid * b <= a * denom )
                numerator = mid, left = mid + 1;
            else
                right = mid - 1;
        }
        left = 0, right = 100000;
        long long num2 = 0, den2 = denom;
        while( left <= right ) {
            long long mid = (left + right) >> 1;
            if( mid * b < a * denom )
                left = mid + 1;
            else
                num2 = mid, right = mid - 1;
        }
        double diff2 = abs(double(num2)/double(den2) - double(a)/double(b));
        double diff1 = abs(double(numerator)/double(denom) - double(a)/double(b));
        if( diff2 + 1e-8 < diff1)
            numerator = num2, denom = den2, diff1 = diff2;
        long long g = compute_gcd(numerator, denom);
        if( diff1 < min_difference )
            best_num = numerator / g, best_den = denom / g, min_difference = diff1;
    }
    cout << best_num << "/" << best_den;
    return 0;
}
